'use strict';
window.RepoJourney=(()=>{const A=RepoAccount;let identity=null,epoch=0,items=new Map(),seen=new Set(),settings={rememberViews:false,hideSeen:false},ready=false,available=false,busy=false,error=null;const notify=()=>window.dispatchEvent(new Event('reposhelf-journey'));const reset=()=>{items=new Map();seen=new Set();settings={rememberViews:false,hideSeen:false};ready=false;available=false;busy=false;error=null};async function load(){const person=A.user?.id;if(person===identity)return;identity=person;const token=++epoch;reset();notify();if(!person){ready=true;notify();return}try{const result=new Map();let cursor,config;do{const data=await A.request('/api/collection?action=discovery'+(cursor?'&cursor='+encodeURIComponent(cursor):''));config=data.settings;for(const row of data.items||[])if(row.viewedAt&&row.repo)result.set(row.id,row);cursor=data.nextCursor}while(cursor&&token===epoch);if(token!==epoch||A.user?.id!==person)return;available=true;items=result;seen=new Set([...items.keys()].map(id=>id.toLowerCase()));settings=config||{rememberViews:false,hideSeen:false}}catch(e){if(token===epoch)error=e.code==='migration_required'?'Viewing history is awaiting an account update.':e.message}finally{if(token===epoch){ready=true;notify()}}}async function configure(next){if(A.legal.required){location.href='/legal.html';return}if(!A.user)throw Error('Sign in with GitHub first.');if(busy)return;const person=A.user.id,token=epoch;busy=true;notify();try{const data=await A.request('/api/collection?action=discovery',{method:'PUT',body:JSON.stringify({action:'settings',...next})});if(person!==A.user?.id||token!==epoch)return;settings=data.settings;error=null}catch(e){if(token===epoch)error=e.message;throw e}finally{busy=false;notify()}}async function remember(repo){if(!ready||!settings.rememberViews||!A.user||A.legal.required||!repo)return;const person=A.user.id,token=epoch;try{const data=await A.request('/api/collection?action=discovery',{method:'PUT',body:JSON.stringify({action:'view',id:repo.full,repo:{name:repo.name,description:repo.description,category:repo.category,language:repo.language,demo:repo.demo}})});if(token!==epoch||person!==A.user?.id||!data.remembered)return;items.set(data.id,{id:data.id,repo:{...repo,full:data.id},viewedAt:data.viewedAt||new Date().toISOString()});seen.add(data.id.toLowerCase());notify()}catch(e){if(token===epoch){error=e.message;notify()}}}async function clear(){if(!A.user||busy)return;const token=epoch;busy=true;notify();try{await A.request('/api/collection?action=discovery',{method:'DELETE',body:'{}'});if(token===epoch){items.clear();seen.clear();error=null}}finally{busy=false;notify()}}window.addEventListener('reposhelf-account',()=>void load());if(A.ready)void load();return {get items(){return new Map(items)},get settings(){return {...settings}},get ready(){return ready},get available(){return available},get busy(){return busy},get error(){return error},load,configure,remember,clear,seen:id=>seen.has(id.toLowerCase())};})();
